import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Resource Library","description":"A problem-first research index: symptom → pyramid chapter → in-chapter resource library and the next question; external knowledge owners (Learn LLM / evals / sites-epub), general tools, and official spec snapshots.","frontmatter":{"title":"Resource Library","description":"A problem-first research index: symptom → pyramid chapter → in-chapter resource library and the next question; external knowledge owners (Learn LLM / evals / sites-epub), general tools, and official spec snapshots.","domain":"tech","tags":["resources","index","research"],"navOrder":95,"topicId":"resources","layer":"resource","status":"canonical","nodeType":"resource","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"resources.md","filePath":"resources.md","lastUpdated":1788429430000}'),n={name:"resources.md"};function s(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="resource-library" tabindex="-1">Resource Library <a class="header-anchor" href="#resource-library" aria-label="Permalink to &quot;Resource Library&quot;">​</a></h1><p><strong>What this is</strong>: a research index, not a link list. Usage: arrive with a <strong>problem</strong> → locate the mainline chapter in the first table → take the leveled reading route from that chapter&#39;s &quot;Resource Library&quot; section → use the &quot;next question&quot; column to decide where to go after reading. For external knowledge, check ownership in the second table first so you never search in the wrong site.</p><h2 id="_1-find-resources-by-problem" tabindex="-1">1. Find resources by problem <a class="header-anchor" href="#_1-find-resources-by-problem" aria-label="Permalink to &quot;1. Find resources by problem&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom / problem</th><th>Where to go first (layer · chapter)</th><th>In-chapter library</th><th>Next question after reading</th></tr></thead><tbody><tr><td>Don&#39;t know where to start; problem domain unclear</td><td>L0 · <a href="/tech/">Tech map</a></td><td>see the chapter&#39;s &quot;Resource Library&quot; section</td><td>Which rung is my need on? → <a href="/tech/00-map/complexity-ladder.html">Complexity decision ladder</a></td></tr><tr><td>Unstable answers; output won&#39;t parse</td><td>L1 · <a href="/tech/02-inference-interface/structured-output.html">Structured output</a></td><td>same</td><td>Parsing is stable but content is off? → L3 grounding</td></tr><tr><td>Prompts are weak; roles and instructions confused</td><td>L1 · <a href="/tech/03-context/prompt.html">Prompt engineering</a></td><td>same</td><td>Is one prompt enough, or do I need project-level context? → <a href="/tech/03-context/context-engineering.html">Context engineering</a></td></tr><tr><td>The model doesn&#39;t know my repo&#39;s conventions</td><td>L1 · <a href="/tech/03-context/context-engineering.html">Context engineering</a></td><td>same</td><td>Context won&#39;t fit or costs too much? → <a href="/tech/08-production/cost-performance.html">Cost &amp; performance</a></td></tr><tr><td>Answers stable but not productized (API calls, streaming, sessions)</td><td>L2 · <a href="/tech/02-inference-interface/model-api.html">Model API contract</a>, <a href="/tech/02-inference-interface/streaming.html">Streaming</a>, <a href="/tech/03-context/session-memory.html">Session &amp; state</a></td><td>same</td><td>Want generative UI? → <a href="/tech/02-inference-interface/ui.html">Generative UI</a></td></tr><tr><td>Answers lack private or fresh facts</td><td>L3 · <a href="/tech/04-grounding/rag.html">RAG</a>, <a href="/tech/04-grounding/embeddings-retrieval.html">Embeddings &amp; retrieval</a></td><td>same</td><td>Retrieval quality maxed out? → <a href="/tech/04-grounding/advanced-retrieval.html">Advanced retrieval</a></td></tr><tr><td>Need to act (call systems, mutate data)</td><td>L4 · <a href="/tech/05-action/tool-execution.html">Tool execution</a> (contract: L1 <a href="/tech/05-action/tool-calling.html">Tool calling</a>)</td><td>same</td><td>Multi-step, recoverable, needs approval? → <a href="/tech/06-agent-systems/agent-runtime.html">Agent runtime</a></td></tr><tr><td>Need an autonomous helper loop</td><td>L4 · <a href="/tech/06-agent-systems/agent-runtime.html">Agent runtime</a></td><td>same</td><td>Context/memory management out of control? → <a href="/tech/06-agent-systems/state-memory.html">State &amp; memory</a></td></tr><tr><td>Collaboration across host / org / agent boundaries</td><td>L4 · <a href="/tech/07-interoperability/index.html">Protocol map</a></td><td>same</td><td>Which protocol? → enter the MCP / A2A / ACP / AG-UI chapters by connection direction</td></tr><tr><td>Feature works but can&#39;t be proven or operated</td><td>L5 · <a href="/tech/08-production/testing.html">Testing</a>, <a href="/tech/08-production/observability.html">Observability</a></td><td>same</td><td>Need release gates and evaluation evidence? → <a href="/tech/08-production/evaluation.html">Evaluation (bridge)</a></td></tr><tr><td>High token cost, high latency</td><td>L5 · <a href="/tech/08-production/cost-performance.html">Cost &amp; performance</a></td><td>same</td><td>Optimize to the end — smaller/edge models? → <a href="/tech/02-inference-interface/browser-edge.html">Browser &amp; edge inference</a></td></tr><tr><td>Time to ship with rollback</td><td>L5 · <a href="/tech/08-production/deployment.html">Deployment &amp; release</a></td><td>same</td><td>Who watches it in production? → <a href="/tech/08-production/observability.html">Observability</a></td></tr><tr><td>Permissions, injection, data safety</td><td>L5 · <a href="/tech/08-production/security.html">Security</a></td><td>same</td><td>Alignment-level misbehavior? → external owner Learn LLM</td></tr><tr><td>Want to move model weights (fine-tune/align)</td><td>Appendix · <a href="/tech/01-model-lifecycle/post-training/index.html">Model lifecycle bridges</a></td><td>see each bridge&#39;s &quot;deep derivations&quot; section</td><td>Derivations &amp; implementation → Learn LLM</td></tr></tbody></table><p>Each chapter&#39;s &quot;Resource Library&quot; section provides a four-level reading route (Beginner → Builder → Operator → Researcher); resources carry source and retrievedAt markers.</p><h2 id="_2-external-knowledge-owners" tabindex="-1">2. External knowledge owners <a class="header-anchor" href="#_2-external-knowledge-owners" aria-label="Permalink to &quot;2. External knowledge owners&quot;">​</a></h2><p>The full cross-repo division is in <a href="/tech/00-map/site-boundaries.html">Site boundaries &amp; ownership</a>; this table is the retrieval-oriented quick view (retrievedAt: 2026-09-01):</p><table tabindex="0"><thead><tr><th>Owner</th><th>Scope</th><th>canonical URL</th><th>When to go</th></tr></thead><tbody><tr><td><strong>Learn LLM</strong></td><td>Model internals, training math (SFT/DPO/LoRA derivations), low-level RAG/Agent theory, multimodal and quantization mechanics</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">https://llm.zenheart.site/</a></td><td>When you need the &quot;why&quot; derivation, internals, or math; the deep target of every bridge page in this repo</td></tr><tr><td><strong>evals</strong></td><td>Evaluation methods, benchmarks, judges, Golden Dataset, release evidence and CI integration</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>When you need evidence for release decisions, eval-set construction, or release-gate wiring</td></tr><tr><td><strong>sites-epub</strong></td><td>Vendor docs/blog captures and offline EPUB indexing</td><td><a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">https://epub.zenheart.site/</a></td><td>When you need vendor originals, offline reading, or version detail checks</td></tr><tr><td><strong>learn-ai</strong> (this site)</td><td>Cross-technology mainline, five-part teaching, decision trees, minimal fixtures, debugging/production experience</td><td><a href="https://ai.zenheart.site/" target="_blank" rel="noreferrer">https://ai.zenheart.site/</a></td><td>When you need the engineering-decision view and end-to-end exercises</td></tr></tbody></table><p>Dynamic site numbers (chapter counts, pricing, availability) are not statically copied here — only URLs and retrievedAt; the target site is authoritative at visit time.</p><h2 id="_3-general-tools-and-community" tabindex="-1">3. General tools and community <a class="header-anchor" href="#_3-general-tools-and-community" aria-label="Permalink to &quot;3. General tools and community&quot;">​</a></h2><p>A curated set of general tools and services, grouped by purpose (vendor commands and parameters belong to sites-epub / vendor docs; this section only answers &quot;when to choose it&quot;):</p><p><strong>UI component libraries</strong> (L2 interaction):</p><ul><li><a href="https://ui.shadcn.com/" target="_blank" rel="noreferrer">Shadcn UI</a> — copy/paste React components; the default starting point for chat interfaces</li><li><a href="https://sdk.vercel.ai/docs/guides/ui" target="_blank" rel="noreferrer">Vercel AI SDK UI</a> — official headless hooks: streaming render, message state, generative-UI companion</li><li><a href="https://nextui.org/" target="_blank" rel="noreferrer">NextUI</a> — beautiful, fast React components; general UI supplement</li></ul><p><strong>AI libraries (TypeScript)</strong> (L2/L3 orchestration):</p><ul><li><a href="https://js.langchain.com/" target="_blank" rel="noreferrer">LangChain.js</a> — chain/agent orchestration, broadest ecosystem</li><li><a href="https://ts.llamaindex.ai/" target="_blank" rel="noreferrer">LlamaIndex.ts</a> — RAG and data ingestion focus</li><li><a href="https://huggingface.co/docs/transformers.js" target="_blank" rel="noreferrer">Transformers.js</a> — in-browser ML (pairs with L2 <a href="/tech/02-inference-interface/browser-edge.html">edge inference</a>)</li></ul><p><strong>Vector databases</strong> (L3 retrieval):</p><ul><li><a href="https://supabase.com/vector" target="_blank" rel="noreferrer">Supabase (pgvector)</a> — lowest-complexity option when you already run Postgres</li><li><a href="https://www.pinecone.io/" target="_blank" rel="noreferrer">Pinecone</a> — specialized serverless vector DB</li><li><a href="https://upstash.com/vector" target="_blank" rel="noreferrer">Upstash Vector</a> — edge-deployment friendly</li></ul><p><strong>Learning</strong>:</p><ul><li><a href="https://www.deeplearning.ai/" target="_blank" rel="noreferrer">DeepLearning.AI</a> — concept-heavy systematic courses</li><li><a href="https://sdk.vercel.ai/docs" target="_blank" rel="noreferrer">Vercel AI SDK docs</a> — among the best practical docs</li><li><a href="https://huggingface.co/course" target="_blank" rel="noreferrer">Hugging Face course</a> — understanding model internals (complements Learn LLM)</li></ul><p><strong>Community</strong>:</p><ul><li><a href="https://github.com/vercel/ai/discussions" target="_blank" rel="noreferrer">Vercel Community</a> — AI SDK issues and direction</li><li><a href="https://discord.gg/langchain" target="_blank" rel="noreferrer">LangChain Discord</a> — orchestration-framework ecosystem</li><li><a href="https://www.reddit.com/r/LocalLLaMA/" target="_blank" rel="noreferrer">/r/LocalLLaMA</a> — densest hub for running local models</li></ul><h2 id="_4-official-spec-snapshots" tabindex="-1">4. Official spec snapshots <a class="header-anchor" href="#_4-official-spec-snapshots" aria-label="Permalink to &quot;4. Official spec snapshots&quot;">​</a></h2><p>Canonical spec addresses cited by the protocol chapters (the SSOT targets of this repo&#39;s protocol content; retrievedAt: 2026-09-01, version claims follow the spec originals):</p><table tabindex="0"><thead><tr><th>Topic</th><th>canonical URL</th></tr></thead><tbody><tr><td>Agent Skills</td><td><a href="https://agentskills.io/specification" target="_blank" rel="noreferrer">https://agentskills.io/specification</a></td></tr><tr><td>Agent Plugins</td><td><a href="https://agent-plugins.org/specification" target="_blank" rel="noreferrer">https://agent-plugins.org/specification</a></td></tr><tr><td>MCP</td><td><a href="https://modelcontextprotocol.io/specification/latest" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/latest</a></td></tr><tr><td>A2A</td><td><a href="https://a2a-protocol.org/v1.0.0/specification/" target="_blank" rel="noreferrer">https://a2a-protocol.org/v1.0.0/specification/</a></td></tr><tr><td>Agent Client Protocol</td><td><a href="https://agentclientprotocol.com/" target="_blank" rel="noreferrer">https://agentclientprotocol.com/</a></td></tr><tr><td>AG-UI</td><td><a href="https://docs.ag-ui.com/introduction" target="_blank" rel="noreferrer">https://docs.ag-ui.com/introduction</a></td></tr><tr><td>A2UI / MCP Apps</td><td><a href="https://a2ui.org/" target="_blank" rel="noreferrer">https://a2ui.org/</a> ｜ <a href="https://modelcontextprotocol.io/extensions/apps/overview" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/extensions/apps/overview</a></td></tr><tr><td>ARD / MCP Registry</td><td><a href="https://agenticresourcediscovery.org/spec/" target="_blank" rel="noreferrer">https://agenticresourcediscovery.org/spec/</a> ｜ <a href="https://github.com/modelcontextprotocol/registry" target="_blank" rel="noreferrer">https://github.com/modelcontextprotocol/registry</a></td></tr><tr><td>JSON Schema / OpenAPI / JSON-RPC</td><td><a href="https://json-schema.org/specification" target="_blank" rel="noreferrer">https://json-schema.org/specification</a> ｜ <a href="https://spec.openapis.org/oas/" target="_blank" rel="noreferrer">https://spec.openapis.org/oas/</a> ｜ <a href="https://www.json-rpc.org/specification" target="_blank" rel="noreferrer">https://www.json-rpc.org/specification</a></td></tr><tr><td>OAuth 2.1 (<strong>draft — never cite as final</strong>) / OIDC / AuthZEN</td><td><a href="https://datatracker.ietf.org/doc/rfc9700/" target="_blank" rel="noreferrer">https://datatracker.ietf.org/doc/rfc9700/</a> ｜ <a href="https://openid.net/specs/openid-connect-core-1_0.html" target="_blank" rel="noreferrer">https://openid.net/specs/openid-connect-core-1_0.html</a> ｜ <a href="https://openid.net/specs/authorization-api-1_0.html" target="_blank" rel="noreferrer">https://openid.net/specs/authorization-api-1_0.html</a></td></tr></tbody></table><p>Each protocol chapter&#39;s &quot;spec vs locally tested&quot; columns take these addresses as the spec-side source; if a spec updates after the snapshot date, update the chapter&#39;s specVersion first, then this table.</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><p>Non-mainline content (training bridges, cases, course notes, methodology archive) lives in the <a href="/tech/appendices/">appendix area</a> and does not participate in this index&#39;s problem-driven order.</p>',27)])])}const b=t(n,[["render",s]]);export{u as __pageData,b as default};
